import React, { useState, useMemo, useEffect } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks } from '../services/api'; // Fetches data from Spotify
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);

  // Fetch data on searchTerm change
  useEffect(() => {
    const fetchTracks = async () => {
      if (searchTerm) {
        try {
          const results = await searchTracks(searchTerm);
          setFilteredTracks(results);
        } catch (error) {
          console.error('Error fetching tracks:', error);
        }
      }
    };
    fetchTracks();
  }, [searchTerm]);

  // Define columns for react-table
  const columns = useMemo(
    () => [
      { Header: 'Track Name', accessor: 'name' },
      { Header: 'Artist Name', accessor: 'artists[0].name' },
      { Header: 'Album Name', accessor: 'album.name' },
      {
        Header: 'Release Date',
        accessor: 'album.release_date',
        Cell: ({ value }) => (value ? value.split('-')[0] : 'Unknown Year'),
      },
      {
        Header: 'Preview',
        accessor: 'id',
        Cell: ({ value }) =>
          value ? (
            <iframe
              src={`https://open.spotify.com/embed/track/${value}`}
              width="100%"
              height="80"
              allow="encrypted-media"
              allowtransparency="true"
              style={{ border: 'none' }}
            ></iframe>
          ) : (
            'No Preview Available'
          ),
      },
    ],
    []
  );

  // Set up table data
  const data = useMemo(() => filteredTracks, [filteredTracks]);
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } = useTable(
    { columns, data },
    useSortBy
  );

  return (
    <div className="track-search-container">
      {filteredTracks.length > 0 ? (
        <table {...getTableProps()} className="results-table">
          <thead>
            {headerGroups.map((headerGroup) => (
              <tr {...headerGroup.getHeaderGroupProps()}>
                {headerGroup.headers.map((column) => (
                  <th {...column.getHeaderProps(column.getSortByToggleProps())}>
                    {column.render('Header')}
                    <span>
                      {column.isSorted ? (
                        column.isSortedDesc ? <ArrowDownwardIcon fontSize="small" /> : <ArrowUpwardIcon fontSize="small" />
                      ) : null}
                    </span>
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody {...getTableBodyProps()}>
            {rows.map((row) => {
              prepareRow(row);
              return (
                <tr {...row.getRowProps()}>
                  {row.cells.map((cell) => (
                    <td {...cell.getCellProps()}>{cell.render('Cell')}</td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p className="no-results">No results found</p>
      )}
    </div>
  );
};

export default TrackSearch;
